set-payload.value:
#[output application/json
---
if ((vars.runStatus default "") == "MISSING_SOURCE_FILE")
{
    status: "NOT_STARTED",
    message: "The expected inventory source file was not found",
    runId: vars.runId,
    sourceFile: vars.sourceFilePath,
    businessDate: vars.businessDate
}
else if ((vars.runStatus default "") == "ALREADY_RUNNING")
{
    status: "NOT_STARTED",
    message: "Another inventory execution is already running",
    runId: vars.runId,
    sourceFile: vars.sourceFilePath,
    businessDate: vars.businessDate
}
else if ((vars.runStatus default "") == "DUPLICATE_FILE")
{
    status: "NOT_STARTED",
    message: "The source file was already processed successfully",
    runId: vars.runId,
    sourceFile: vars.sourceFilePath,
    businessDate: vars.businessDate
}
else
{
    status: "ACCEPTED",
    message: "Inventory Batch Job was submitted successfully",
    runId: vars.runId,
    sourceFile: vars.sourceFilePath,
    businessDate: vars.businessDate
}]
